import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    // Read an integer N from the input
    int N = sc.nextInt();

    String strL = "L";
    StringBuilder strO = new StringBuilder("o");
    String strN = "n";
    String strG = "g";

    // Append the character 'o' to strO N-1 times
    for (int i = 1; i < N; i++) {
        strO.append("o");
    }

    // Concatenate strL, strO, strN, and strG into a single string and print
    System.out.println(strL + strO + strN + strG);
}
